<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import StatusNotice from '../components/StatusNotice.vue'
import { adminRedPacketApi, adminSession, isApiRequestError, type AdminRedPacketClaimsPage, type AdminRedPacketLedger, type AdminRedPacketResource, type AdminRedPacketSessionsPage } from '../services'

const route = useRoute(); const router = useRouter(); const id = computed(() => String(route.params.id ?? ''))
const campaign = ref<AdminRedPacketResource>(); const sessions = ref<AdminRedPacketSessionsPage>(); const claims = ref<AdminRedPacketClaimsPage>(); const ledger = ref<AdminRedPacketLedger>(); const tab = ref<'overview'|'sessions'|'claims'|'ledger'>('overview'); const loading = ref(true); const error = ref(''); const forbidden = ref(false)
function money(value?: number) { return value === undefined ? '暂无' : new Intl.NumberFormat('zh-CN', { style: 'currency', currency: 'CNY' }).format(value / 100) }
function date(value?: string) { return value ? new Date(value).toLocaleString('zh-CN') : '暂无' }
function message(caught: unknown) { if (isApiRequestError(caught)) { if (caught.status === 401) adminSession.clear(); forbidden.value = caught.status === 403; return caught.message } return '红包活动详情暂时无法加载，请稍后重试' }
async function load() { loading.value = true; error.value = ''; forbidden.value = false; try { campaign.value = await adminRedPacketApi.campaign(id.value); const [sessionResult, claimResult] = await Promise.all([adminRedPacketApi.sessions(id.value), adminRedPacketApi.claims(id.value)]); sessions.value = sessionResult; claims.value = claimResult; if (adminSession.hasPermission('redpacket.finance')) ledger.value = await adminRedPacketApi.ledger(id.value) } catch (caught) { error.value = message(caught) } finally { loading.value = false } }
function back() { void router.push({ name: 'ADM-RP-001' }) }
onMounted(() => { void load() })
</script>
<template><article class="page red-packet-detail-page"><header class="page-heading"><div><div class="eyebrow">红包运营 / 活动详情</div><h1>红包活动 {{ campaign?.id || id }}</h1><p>库存、会话、领取和资金账本均以服务端响应为准；敏感金额需要独立财务权限。</p></div><div class="page-actions"><button class="ghost-button" @click="back">返回活动列表</button><button class="ghost-button" :disabled="loading" @click="load">刷新</button></div></header><StatusNotice v-if="forbidden" tone="danger" title="没有红包读取权限" detail="当前账号无权读取此活动或其关联数据。"/><StatusNotice v-if="error" tone="danger" title="详情未加载" :detail="error"/><section v-if="loading" class="card skeleton-stack"><div v-for="n in 5" :key="n" class="skeleton skeleton-tall"/></section><template v-else-if="campaign"><section class="detail-grid"><div><dt>当前状态</dt><dd><span class="status-chip" :data-status="campaign.status">{{ campaign.status }}</span></dd></div><div><dt>库存</dt><dd>{{ campaign.remainingCount }} / {{ campaign.totalCount }}</dd></div><div><dt>单个金额</dt><dd>{{ money(campaign.amountPerClaimCent) }}</dd></div><div><dt>服务端版本</dt><dd>v{{ campaign.version }}</dd></div></section><nav class="detail-tabs" aria-label="活动详情页签"><button :class="{active:tab==='overview'}" @click="tab='overview'">概览</button><button :class="{active:tab==='sessions'}" @click="tab='sessions'">会话与锁定 ({{ sessions?.items.length ?? 0 }})</button><button :class="{active:tab==='claims'}" @click="tab='claims'">领取记录 ({{ claims?.items.length ?? 0 }})</button><button :class="{active:tab==='ledger'}" @click="tab='ledger'">资金账本</button></nav><section v-if="tab==='overview'" class="card detail-panel"><dl class="facts-grid"><div><dt>内容 ID</dt><dd>{{ campaign.contentId || '暂无' }}</dd></div><div><dt>发起用户</dt><dd>{{ campaign.ownerUserId || '脱敏' }}</dd></div><div><dt>本金</dt><dd>{{ money(campaign.principalCent) }}</dd></div><div><dt>服务费</dt><dd>{{ money(campaign.serviceFeeCent) }}</dd></div><div><dt>开始时间</dt><dd>{{ date(campaign.startAt) }}</dd></div><div><dt>结束时间</dt><dd>{{ date(campaign.endAt) }}</dd></div></dl><p class="detail-copy">操作审计由服务端保存。平台风险处置请进入“红包风险事件”；409 版本冲突必须刷新后重新确认。</p></section><section v-else-if="tab==='sessions'" class="card detail-panel"><div v-if="!sessions?.items.length" class="compact-empty">暂无浏览会话或名额锁定记录。</div><table v-else class="data-table"><thead><tr><th>会话</th><th>状态</th><th>进度</th><th>过期时间</th><th>版本</th></tr></thead><tbody><tr v-for="item in sessions.items" :key="item.id"><td>{{ item.id }}</td><td>{{ item.status }}</td><td>{{ item.accumulatedSeconds }} / {{ item.requiredSeconds }} 秒</td><td>{{ date(item.expiresAt) }}</td><td>v{{ item.version }}</td></tr></tbody></table></section><section v-else-if="tab==='claims'" class="card detail-panel"><div v-if="!claims?.items.length" class="compact-empty">暂无领取记录。</div><table v-else class="data-table"><thead><tr><th>领取编号</th><th>状态</th><th>金额</th><th>金额版本</th><th>创建时间</th></tr></thead><tbody><tr v-for="item in claims.items" :key="item.id"><td>{{ item.id }}</td><td>{{ item.status }}</td><td>{{ money(item.amountCent) }}</td><td>{{ item.amountVersion }}</td><td>{{ date(item.createdAt) }}</td></tr></tbody></table></section><section v-else class="card detail-panel"><StatusNotice v-if="!adminSession.hasPermission('redpacket.finance')" tone="warning" title="需要财务读取权限" detail="账本数据不会在未授权会话中展示。"/><div v-else-if="!ledger?.items.length" class="compact-empty">当前活动暂无资金账本分录。</div><table v-else class="data-table"><thead><tr><th>分录</th><th>类型</th><th>金额</th><th>余额</th><th>业务标识</th><th>记账时间</th></tr></thead><tbody><tr v-for="item in ledger.items" :key="item.id"><td>{{ item.id }}</td><td>{{ item.entryType || '未分类' }}</td><td>{{ money(item.amountCent) }}</td><td>{{ money(item.balanceAfterCent) }}</td><td>{{ item.bizId || '暂无' }}</td><td>{{ date(item.createdAt) }}</td></tr></tbody></table></section></template></article></template>
